import { describe, expect, test } from "vitest";
import { clamp } from "./clamp";
import { pipe } from "./pipe";

describe("reversed finite bounds", () => {
  test("normalizes bounds for data-first use", () => {
    expect(clamp(1, { min: 10, max: 0 })).toBe(1);
    expect(clamp(-1, { min: 10, max: 0 })).toBe(0);
    expect(clamp(11, { min: 10, max: 0 })).toBe(10);
  });

  test("normalizes bounds for data-last use", () => {
    const limits = { min: 10, max: 0 };
    const clampWithLimits = clamp(limits);

    expect(clampWithLimits(1)).toBe(1);
    expect(clampWithLimits(-1)).toBe(0);
    expect(clampWithLimits(11)).toBe(10);
  });

  test("normalizes bounds in pipe use", () => {
    expect(pipe(-1, clamp({ min: 10, max: 0 }))).toBe(0);
    expect(pipe(11, clamp({ min: 10, max: 0 }))).toBe(10);
  });

  test("does not mutate limits, including frozen limits", () => {
    const limits = Object.freeze({ min: 10, max: 0 });

    expect(clamp(1, limits)).toBe(1);
    expect(limits).toStrictEqual({ min: 10, max: 0 });
  });

  test("observes limits changes for each curried invocation", () => {
    const limits: { min: number; max: number } = { min: 10, max: 0 };
    const clampWithLimits = clamp(limits);

    expect(clampWithLimits(11)).toBe(10);
    limits.min = 20;
    limits.max = 5;
    expect(clampWithLimits(11)).toBe(11);
  });
});

describe("existing bound behavior", () => {
  test("does not normalize NaN or infinite bounds", () => {
    expect(clamp(10, { min: Number.NaN, max: 5 })).toBe(5);
    expect(clamp(10, { min: 5, max: Number.NaN })).toBe(10);
    expect(clamp(10, { min: Number.POSITIVE_INFINITY, max: Number.NEGATIVE_INFINITY })).toBe(
      Number.POSITIVE_INFINITY,
    );
  });

  test("preserves NaN values", () => {
    expect(clamp(Number.NaN, { min: 10, max: 0 })).toBeNaN();
  });
});

