const indexes = [
  1.5,
  -1.5,
  -0,
  0,
  Number.NaN,
  Number.POSITIVE_INFINITY,
  Number.NEGATIVE_INFINITY,
];

describe.each(indexes)("slice normalization for index %s", (index) => {
  const expected = [input.slice(0, index), input.slice(index)];

  test("data-first", () => {
    expect(splitAt(input, index)).toStrictEqual(expected);
  });

  test("data-last", () => {
    expect(splitAt(index)(input)).toStrictEqual(expected);
  });

  test("pipe", () => {
    expect(pipe(input, splitAt(index))).toStrictEqual(expected);
  });
});

